                     RQ(:,5) = 0   ! keeps a one-reader list from looking like the empty sentinel
                     do icls = kc0, kc1
                        ird0 = (icls - kc0) * n4aaab
                        select case (icls)
                        case (1)
                           do idet = 1, n4aaab
                              RQ(ird0+idet,1) = t4b_excits(idet,4); RQ(ird0+idet,2) = t4b_excits(idet,5); RQ(ird0+idet,3) = t4b_excits(idet,6); RQ(ird0+idet,4) = t4b_excits(idet,8);
                           end do
