                           nneed = 0
                           do jr = rind%off(kdx), rind%off(kdx+1)-1
                              ird = rind%perm(jr); icls = kc0 + (ird-1)/n4aaab; idet = mod(ird-1, n4aaab) + 1
                              select case (icls)
