                                 a = t4b_excits(idet,1); b = t4b_excits(idet,2); c = t4b_excits(idet,3); k = t4b_excits(idet,7);
                                 idx = pspace_find(key_vaaa31, nblk_vaaa31, pspace_key((/a,b,c,k/), 4, vdims_vaaa31, vchain_vaaa31))
                                 rp(ird) = idx
