                        !$omp end parallel
                        ndk = 0
                        do kdx = kch0, kch1
                           kmslot(kdx-kch0+1) = 0
                           if (8*kmnn(kdx-kch0+1) >= noa*noa) then
                              ndk = ndk + 1; kmdk(ndk) = kdx; kmslot(kdx-kch0+1) = ndk
                           end if
                        end do
                        if (ndk > 0) then
                           kmRB(:,1:ndk) = 0.0d0
                           ! IX += +1 * H2A_ooov(xyiu) * t2b(udjl), one GEMM per value of i
                           allocate(kmcnt(noa+1), kmord(ndk))
                           kmcnt = 0
                           do kmi = 1, ndk
