                              case (1)
                                 do jdet = off_vaaa31(idx), off_vaaa31(idx+1)-1
                                    x = vaaa31_excits(jdet,5); y = vaaa31_excits(jdet,6)
                                    val = val + vaaa31_amps(jdet) * ((+1)*IX(x,y) + (-1)*IX(y,x))
                                 end do
                              case (2)
                                 do jdet = off_vaaa31(idx), off_vaaa31(idx+1)-1
                                    x = vaaa31_excits(jdet,5); y = vaaa31_excits(jdet,6)
                                    val = val + vaaa31_amps(jdet) * ((+1)*IX(x,y) + (-1)*IX(y,x))
                                 end do
                                 val = -val
                              case (3)
                                 do jdet = off_vaaa31(idx), off_vaaa31(idx+1)-1
                                    x = vaaa31_excits(jdet,5); y = vaaa31_excits(jdet,6)
                                    val = val + vaaa31_amps(jdet) * ((+1)*IX(x,y) + (-1)*IX(y,x))
                                 end do
                              end select
                              end if
                              if (val /= 0.0d0) then
