                  ! key-major: I3A_vooooo(cxykij) x taab(abdxyl), 18 classes share IX(q)
                  kbat = max(1, min(18, 16777216 / max(1, n4aaab)))
                  do kc0 = 1, 18, kbat
                     kc1 = min(18, kc0 + kbat - 1)
                     nrd = (kc1 - kc0 + 1) * n4aaab
                     allocate(RQ(nrd,5), rp(nrd))
                     RQ(:,5) = 0   ! keeps a one-reader list from looking like the empty sentinel
                     do icls = kc0, kc1
                        ird0 = (icls - kc0) * n4aaab
                        select case (icls)
                        case (1)
                           do idet = 1, n4aaab
                              RQ(ird0+idet,1) = t4b_excits(idet,1); RQ(ird0+idet,2) = t4b_excits(idet,5); RQ(ird0+idet,3) = t4b_excits(idet,6); RQ(ird0+idet,4) = t4b_excits(idet,7);
                           end do
