                           do idet = 1, n4aaab
                              RQ(ird0+idet,1) = t4b_excits(idet,3); RQ(ird0+idet,2) = t4b_excits(idet,5); RQ(ird0+idet,3) = t4b_excits(idet,6); RQ(ird0+idet,4) = t4b_excits(idet,7);
                           end do
                        case (4)
                           do idet = 1, n4aaab
                              RQ(ird0+idet,1) = t4b_excits(idet,1); RQ(ird0+idet,2) = t4b_excits(idet,5); RQ(ird0+idet,3) = t4b_excits(idet,7); RQ(ird0+idet,4) = t4b_excits(idet,6);
                           end do
