                                    a = t4b_excits(idet,1); b = t4b_excits(idet,2); d = t4b_excits(idet,4); k = t4b_excits(idet,7);
                                    idx = pspace_find(key_vaab2110, nblk_vaab2110, pspace_key((/a,b,d,k/), 4, vdims_vaab2110, vchain_vaab2110))
